import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.D_J2JZBr.js";const b=JSON.parse('{"title":"推免与直博","description":"理清推免资格、接收考核和正式系统录取，核对上科大及上海创芯学院的年度通知。","frontmatter":{"title":"推免与直博","description":"理清推免资格、接收考核和正式系统录取，核对上科大及上海创芯学院的年度通知。"},"headers":[],"relativePath":"career/graduate-study/baoyan.md","filePath":"career/graduate-study/baoyan.md","lastUpdated":1795531638000}'),h={name:"career/graduate-study/baoyan.md"};function i(o,t,l,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="推免与直博" tabindex="-1">推免与直博 <a class="header-anchor" href="#推免与直博" aria-label="Permalink to &quot;推免与直博&quot;">​</a></h1><p>推荐免试（通常称“保研”）包含两个不同环节：本科学校授予推荐资格，接收单位考核并决定是否接收。夏令营、预推免面试和拟接收函都不能代替正式录取程序；只有接收意向、却没有推免资格，也不能直接走完推免。</p><h2 id="常见时间线" tabindex="-1">常见时间线 <a class="header-anchor" href="#常见时间线" aria-label="Permalink to &quot;常见时间线&quot;">​</a></h2><p>下表是通用规划，不是任何学校的固定日程。“九推”是学生对秋季推免阶段的俗称，具体系统开放时间与各校安排可能不同。</p><table tabindex="0"><thead><tr><th>时间段</th><th>常见事项</th><th>建议产物</th></tr></thead><tbody><tr><td>大三春季，约 3–5 月</td><td>确认本校资格规则，梳理方向与项目</td><td>学校 / 导师清单、材料目录</td></tr><tr><td>约 5–7 月</td><td>夏令营申请与活动</td><td>针对性简历、个人陈述、面试 slide</td></tr><tr><td>约 7–9 月</td><td>预推免报名、分批考核</td><td>官方通知与截止日期表</td></tr><tr><td>9 月及秋季正式阶段</td><td>确认资格，在教育部系统完成相应操作</td><td>复试、待录取等状态的正式核对记录</td></tr><tr><td>接收后至入学前</td><td>完成毕业、体检等要求</td><td>按通知补齐材料，不遗漏资格复核</td></tr></tbody></table><p>日历中分别记录“提交申请”“补材料”“面试”“确认意向”和“正式系统确认”，不要只记最后一天。通知常会更新或分批发布，旧经验仅用于准备，不能代替当年规则。</p><h2 id="上科大-两类入口不要混用" tabindex="-1">上科大：两类入口不要混用 <a class="header-anchor" href="#上科大-两类入口不要混用" aria-label="Permalink to &quot;上科大：两类入口不要混用&quot;">​</a></h2><h3 id="信息学院接收-2027-级推免生" tabindex="-1">信息学院接收 2027 级推免生 <a class="header-anchor" href="#信息学院接收-2027-级推免生" aria-label="Permalink to &quot;信息学院接收 2027 级推免生&quot;">​</a></h3><p>学院 2026 年 7 月 31 日通知中，学术型专业包括 081200 计算机科学与技术（含直博、含应用数学方向）、080900 电子科学与技术（含直博）及 081000 信息与通信工程；专业型为 085400 电子信息（含直博）。这里的“含直博”按通知标注，不能推及所有专业或导师。</p><p>该批次学术型申请要求填报三位意向导师，建议提前邮件沟通但不是强制要求；专业型按研究方向申请，无需选报导师。通知明确两类研招不能同时报名。学术学位直博还需联系导师，获得推荐并提交正式师生互选协议。</p><h3 id="上海创芯学院与上科大联合推免" tabindex="-1">上海创芯学院与上科大联合推免 <a class="header-anchor" href="#上海创芯学院与上科大联合推免" aria-label="Permalink to &quot;上海创芯学院与上科大联合推免&quot;">​</a></h3><p>2026 年 8 月 15 日通知面向 2027 届可获推免资格的本科生，申请入口为“上海创芯学院”，专业选择电子信息（0854）专业学位（含直博），该通知要求无需选报导师。毕业授予上海科技大学相应专业学位。培养特点见<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/programs">项目介绍</a>。</p><div class="warning custom-block"><p class="custom-block-title">这里是年度通知解读，不是当前报名公告</p><p>上述两份通知所列该批次截止日期均为 2026 年 8 月 23 日，均说明可能顺延、以系统为准。学院后续另有联合推免第二批通知。已过去的日期仅用于理解年度节奏，下一届必须重新核查。拟接收与教育部系统程序不同；通知中的接收承诺及限制应完整阅读后再决定。</p></div><h2 id="材料怎么准备" tabindex="-1">材料怎么准备 <a class="header-anchor" href="#材料怎么准备" aria-label="Permalink to &quot;材料怎么准备&quot;">​</a></h2><p>上面两份通知的必需材料均包含有效身份证件、学生证、中英文个人陈述、中英文简历、成绩单与英语水平证明；奖项和原创成果等为自愿补充。具体合并顺序、命名、提交格式以所报批次为准。</p><p>把完整材料仅提交到官方指定系统，不上传公开仓库。公开简历与展示 slide 应隐藏身份证号、学号、成绩单细节和私人联系方式。推荐信是否需要、推荐人如何提交等，各校不同，不能按一个项目的清单推断所有项目。</p><p>个人陈述重点回答研究兴趣如何形成、已有能力与证据、为什么匹配该培养项目，以及希望继续解决什么问题。项目描述明确个人负责部分、验证办法和失败分析，不用团队总成果代替自己的贡献。</p><h2 id="面试常见问题方向" tabindex="-1">面试常见问题方向 <a class="header-anchor" href="#面试常见问题方向" aria-label="Permalink to &quot;面试常见问题方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>应能解释的基础与项目问题</th></tr></thead><tbody><tr><td>数字 / 架构</td><td>时序逻辑、流水线冲突、存储层次、验证；设计为什么这样取舍？</td></tr><tr><td>模拟 / 射频</td><td>晶体管工作区、小信号、反馈、噪声；指标之间如何权衡？</td></tr><tr><td>器件 / 工艺</td><td>能带、载流子、MOS 结构、测量；模型适用范围是什么？</td></tr><tr><td>EDA</td><td>数据结构、图算法、优化、复杂度；如何验证正确与可扩展？</td></tr><tr><td>共通项目深挖</td><td>问题、方案、个人贡献、基线、结果、失败、下一步</td></tr></tbody></table><p>以上是准备范围，不是上科大的题库。准备 1 分钟和 5 分钟两版项目介绍；英文部分优先练准确解释自己的工作。不知道的问题可以说明已知前提并尝试推理，不应编造结果或术语。</p><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>投稿推免或直博经验，注明年份、项目与公开通知来源；不公开个人录取材料、未经允许的面试题或其他申请者信息。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/2026/0731/c7339a1126058/page.htm" target="_blank" rel="noreferrer">信息学院接收 2027 级推免生通知</a></li><li><a href="https://sist.shanghaitech.edu.cn/2026/0815/c2863a1126312/page.htm" target="_blank" rel="noreferrer">上海创芯学院与上科大接收 2027 级推免生通知</a></li><li><a href="https://sist.shanghaitech.edu.cn/2026/0903/c7339a1126777/page.htm" target="_blank" rel="noreferrer">联合推免第二批通知</a></li><li><a href="https://yz.chsi.com.cn/tm/" target="_blank" rel="noreferrer">教育部推免服务系统与说明</a></li></ul>',23)])])}const u=a(h,[["render",i]]);export{b as __pageData,u as default};
